function stable(s){let a=2166136261,b=5381;for(let i=0;i<s.length;i++){a=Math.imul(a^s.charCodeAt(i),16777619);b=Math.imul(b,33)^s.charCodeAt(i);}return(a>>>0).toString(36)+(b>>>0).toString(36);}
function stripFront(text){return text.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n/,'');}
