const count=list=>({all:list.length,done:list.filter(t=>status(t)==='done').length,pending:list.filter(t=>status(t)==='pending').length,doing:list.filter(t=>status(t)==='doing').length,blocked:list.filter(t=>status(t)==='blocked').length});
