function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Browser storage is unavailable. Export your progress to keep it.');}renderSidebar();renderFooter();}
function setTask(id,patch){if(!byId.has(id))return;state.tasks[id]={...state.tasks[id],...patch,updated:new Date().toISOString()};const entry=state.tasks[id];if(!entry.status&&!entry.focus&&!entry.note)delete state.tasks[id];save();}
function applyChecklistSnapshot(snapshot){const master=resolve('Task Checklist');if(!master||!Array.isArray(snapshot.tasks))return;writer={available:true,hash:snapshot.hash,detail:'Writes checkbox completion to Task Checklist.md'};if(typeof snapshot.text==='string'){master.text=snapshot.text;master.lines=snapshot.text.split(/\r?\n/);}const current=new Map(snapshot.tasks.map(item=>[`${item.line}|${item.title}`,item.done?'done':'pending']));for(const task of master.tasks){const next=current.get(`${task.line}|${task.title}`);if(!next)continue;task.source=next;const saved=local(task);if((saved.status==='done'||saved.status==='pending')&&saved.status===next){delete saved.status;if(!saved.focus&&!saved.note)delete state.tasks[task.id];}}save();}
async function refreshChecklistWriter(){if(location.protocol!=='http:')return;try{const response=await fetch('/api/checklist',{cache:'no-store'});if(!response.ok)throw Error(`HTTP ${response.status}`);applyChecklistSnapshot(await response.json());render();}catch(error){writer={available:false,hash:'',detail:'Checklist writer unavailable'};render();}}
async function persistCheckbox(task,done){if(!task.master||!writer.available){setTask(task.id,{status:done?'done':'pending'});updateAfterTask();toast('Saved in this browser only; open the registered local dashboard to update Markdown.');return;}try{const response=await fetch('/api/checklist-task',{method:'PATCH',headers:{'Content-Type':'application/json','X-Local-Setup-Writer':'checkbox-v1'},body:JSON.stringify({expectedHash:writer.hash,line:task.line,title:task.title,done})});const result=await response.json();if(response.status===412){applyChecklistSnapshot(result);updateAfterTask();toast('Task Checklist.md changed elsewhere. Refreshed without overwriting it.');return;}if(!response.ok)throw Error(result.error||`HTTP ${response.status}`);applyChecklistSnapshot(result);updateAfterTask();toast(done?'Completed in Task Checklist.md.':'Reopened in Task Checklist.md.');}catch(error){toast(`Markdown was not changed: ${error.message||error}`);}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function navigate(page,options={}){closeDrawer();view={...view,page,q:'',limit:60,...options};location.hash=page==='reader'?`note=${enc(options.note)}${options.anchor?'&anchor='+enc(options.anchor):''}`:page;render();window.scrollTo(0,0);}
function openNote(name,anchor=''){const n=resolve(name);if(!n){toast('This linked note is outside the included Local_Setup folder.');return;}if(view.page==='reader')historyStack.push({note:view.note,anchor:view.anchor});else readerPrevious=view.page;navigate('reader',{note:n.name,anchor});}
function renderSidebar(){const focus=tasks.filter(t=>isFocused(t)&&status(t)!=='done');const navs=[['overview','home','Overview',''],['focus','focus','Focus board',focus.length],['tasks','tasks','All tasks',tasks.filter(t=>t.role==='action').length],['library','book','Note library',notes.length],['completed','check','Completed',tasks.filter(t=>t.role==='action'&&status(t)==='done').length]];
 $('#sidebar').innerHTML=`<div class="brand"><span class="brand-symbol">${icon('layers')}</span><div><strong>LOCAL SETUP</strong><small>YOUR FIELD GUIDE</small></div></div><div class="nav-label">Navigate</div><nav aria-label="Main navigation">${navs.map(([p,i,l,c])=>`<button class="nav-btn ${view.page===p?'active':''}" data-action="nav" data-page="${p}" ${p==='tasks'?'data-scope="all"':''} ${view.page===p?'aria-current="page"':''}>${icon(i)}<span>${l}</span><span class="nav-count">${c}</span></button>`).join('')}</nav><div class="rail-divider"></div><div class="nav-label">On your desk</div>${focus.slice(0,5).map(t=>`<button class="rail-task" data-action="detail" data-id="${t.id}" title="${esc(t.title)}">${esc(t.title)}</button>`).join('')||'<p class="rail-caption">Pin a task to keep it here.<br>Switch context without losing your place.</p>'}<div class="sidebar-bottom"><button class="nav-btn ${view.page==='settings'?'active':''}" data-action="nav" data-page="settings">${icon('settings')}<span>Data & preferences</span></button><div class="source-tag">${icon('shield')}<span>Private, on this device.<br>No account. No network required.</span></div></div>`;
}
function renderFooter(){$('#footer').innerHTML=`<span>${writer.available?'Pending/Completed syncs to Task Checklist.md':'Task progress is browser-only'} · Focus pins and notes stay in this browser</span><span>${notes.length} notes · Snapshot ${stamp(data.generated)}</span>`;}
function heading(eyebrow,title,subtitle,action=''){return`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function searchBox(id,placeholder,value='',extra=''){return`<label class="searchbox ${extra}">${icon('search')}<input id="${id}" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(value)}" autocomplete="off"><kbd>/</kbd></label>`;}
function groupCard(g){const c=count(g.tasks),meta=schedule[g.id]||{};return`<button class="stream" data-action="group" data-group="${g.id}"><div class="stream-top"><span class="seq">SEQUENCE ${g.id}</span><span class="badge ${meta.type||''}">${esc(meta.tag||g.priority||'Later exploration')}</span></div><h3>${esc(meta.title||g.title.replace(/^Sequence \S+\s+[—–-]\s*/,''))}</h3><p>${esc(meta.hint||g.goal)}</p><div class="stream-bottom"><div class="stream-meter"><span>${c.done} / ${c.all} checked steps</span><span>${esc(g.time.match(/\d+(?:[.\d–-]*\d)?\s*(?:hours?|minutes?)/)?.[0]||`${c.all-c.done} remaining`)}</span></div><div class="mini-progress"><span style="width:${c.all?100*c.done/c.all:0}%"></span></div></div></button>`;}
function renderOverview(){const primary=tasks.filter(t=>t.role==='action'),c=count(primary),op=tasks.filter(t=>t.master&&operation.has(t.group)),o=count(op),focus=tasks.filter(t=>isFocused(t)&&status(t)!=='done');const recovery=groupMap.get('1');const next=recovery?.tasks.find(t=>status(t)!=='done');const index=resolve('Local Setup Index');const hasQwen=index?.text.includes('10 GiB')&&index.text.includes('startup capacity and request validation remain pending');
 return heading('The big picture','Your setup, in perspective.','One place for the work ahead, the progress behind you, and every guide along the way.',searchBox('overview-search','Find a note or topic…','','overview-search'))+
 `<div class="stats"><div class="stat accent"><div class="stat-label">${icon('check')} Checklist steps completed</div><div class="stat-number">${c.done}<span style="font-size:15px;letter-spacing:0;font-weight:400;color:var(--muted)"> / ${c.all}</span></div><div class="mini-progress"><span style="width:${100*c.done/c.all}%"></span></div><div class="stat-foot">${writer.available?'Live from Task Checklist.md':'Recorded checks + browser updates'}</div></div><div class="stat"><div class="stat-label">${icon('tasks')} Operational steps left</div><div class="stat-number">${o.all-o.done}</div><div class="stat-foot">Sequences 0, 1, 3A, 4, 5 and 6</div></div><div class="stat"><div class="stat-label">${icon('focus')} On your focus board</div><div class="stat-number">${focus.length.toString().padStart(2,'0')}</div><div class="stat-foot">${focus.filter(t=>status(t)==='doing').length} in progress · ${focus.filter(t=>status(t)==='blocked').length} blocked</div></div><div class="stat"><div class="stat-label">${icon('book')} Notes within reach</div><div class="stat-number">${notes.length}</div><div class="stat-foot">Guides, research and operating references</div></div></div>`+
 `<div class="hero-grid"><section class="start-panel"><div class="eyebrow">${focus.length?'Your active workspace':'A good place to continue'}</div><h2>${focus.length?'Pick up where you left off.':'Make the foundation dependable.'}</h2><p>${focus.length?'Your pinned tasks stay together, with status and notes for each thread of work.':'The checklist puts backups, a safe restore, and restart recovery first. Keep one infrastructure session in charge.'}</p>${btn(`${focus.length?'Open focus board':'Review the next recovery step'} ${icon('arrow')}`,focus.length?'nav':'detail',focus.length?'data-page="focus"':`data-id="${next?.id||''}"`,'primary')}</section><section class="small-panel"><div class="panel-top"><h3>Navigate by source</h3><span class="badge green">Start here</span></div>${[['Local Setup Index','Current state & resume order'],['Task Checklist','Work blocks & completion gates'],['DGX Spark Dual-Node Configuration And Operations Reference','Current two-node operations']].map(([name,sub])=>`<div class="timeline-item"><i></i><button data-action="note" data-note="${esc(name)}">${esc(name==='DGX Spark Dual-Node Configuration And Operations Reference'?'Dual-Spark reference':name)}<span>${sub}</span></button></div>`).join('')}</section></div>`+
 (hasQwen?`<div class="issue">${icon('info')}<p><strong>Source update to review.</strong> The index says the new Qwen 10 GiB profile still needs startup and request validation. Older completion entries describe the previous profile.</p><button data-action="note" data-note="Local Setup Index" data-anchor="Architecture and research completed">Read the update ↗</button></div>`:'')+
 `<div class="section-head"><div><h2>Workstreams, with room to focus.</h2><p>Scheduling guidance from the checklist. Read each completion gate before moving on.</p></div>${btn('All sequences '+icon('arrow'),'nav','data-page="tasks" data-scope="all"','text')}</div><div class="workstreams">${['1','3A','4','5','6','6B'].map(id=>groupMap.get(id)).filter(Boolean).map(groupCard).join('')}</div><div class="section-head"><div><h2>The rest of the field guide</h2><p>Optional work stays available when you’re ready for it.</p></div></div><div class="essential-grid"><button class="essential" data-action="group" data-group="8I"><span class="tile-icon">${icon('layers')}</span><span><strong>Models & dual-Spark exploration</strong><small>Readiness gates, exclusive lanes and staged qualification</small></span>${icon('arrow')}</button><button class="essential" data-action="nav" data-page="library"><span class="tile-icon">${icon('book')}</span><span><strong>Browse all ${notes.length} notes</strong><small>Search the full content. Follow links without leaving the page.</small></span>${icon('arrow')}</button></div>`;
}
function scopeTasks(scope){switch(scope){case'operational':return tasks.filter(t=>t.role==='action'&&operation.has(t.group));case'later':return tasks.filter(t=>t.role==='action'&&!operation.has(t.group));case'summary':return tasks.filter(t=>t.role==='summary');case'reference':return tasks.filter(t=>t.role==='reference');default:return tasks.filter(t=>t.role==='action');}}
